use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde_json::{Value, Map};
use std::sync::Mutex;
use std::collections::HashMap;

// Global configuration store - shared mutable state
struct AppState {
    config: Mutex<Value>,
    user_preferences: Mutex<HashMap<String, Value>>,
}

// Deep merge utility - merges source into target recursively
fn deep_merge(target: &mut Value, source: &Value) {
    match (target, source) {
        (Value::Object(ref mut target_map), Value::Object(source_map)) => {
            for (key, value) in source_map {
                let entry = target_map.entry(key.clone()).or_insert(Value::Null);
                deep_merge(entry, value);
            }
        }
        (target, source) => {
            *target = source.clone();
        }
    }
}

// Endpoint: update user preferences with deep merge
async fn update_preferences(
    req: HttpRequest,
    body: web::Json<Value>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let user_id = req
        .headers()
        .get("X-User-ID")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("anonymous")
        .to_string();

    // Merge user-supplied JSON into the global config prototype
    // This allows users to "inherit" defaults while customizing
    let mut config = data.config.lock().unwrap();
    let mut prefs = data.user_preferences.lock().unwrap();

    let user_base = prefs
        .entry(user_id.clone())
        .or_insert_with(|| config.clone());

    // VULNERABILITY: Unrestricted deep merge of attacker-controlled JSON
    // into shared config object. Keys like "__proto__", "constructor",
    // or "admin" can pollute the base config for ALL users.
    deep_merge(&mut config, &body);
    deep_merge(user_base, &body);

    HttpResponse::Ok().json(&*config)
}

// Endpoint: get current effective config (shows pollution)
async fn get_config(data: web::Data<AppState>) -> HttpResponse {
    let config = data.config.lock().unwrap();
    HttpResponse::Ok().json(&*config)
}

// Endpoint: check if user is admin (reads from polluted config)
async fn check_admin(
    req: HttpRequest,
    data: web::Data<AppState>,
) -> HttpResponse {
    let config = data.config.lock().unwrap();
    let is_admin = config
        .get("permissions")
        .and_then(|p| p.get("admin"))
        .and_then(|a| a.as_bool())
        .unwrap_or(false);

    if is_admin {
        HttpResponse::Ok().body("Admin access granted. Secret: FLAG{prototype_polluted}")
    } else {
        HttpResponse::Forbidden().body("Access denied")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let initial_config = serde_json::json!({
        "theme": "dark",
        "language": "en",
        "permissions": {
            "admin": false,
            "read": true,
            "write": false
        },
        "features": {
            "beta": false
        }
    });

    let data = web::Data::new(AppState {
        config: Mutex::new(initial_config),
        user_preferences: Mutex::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .route("/preferences", web::post().to(update_preferences))
            .route("/config", web::get().to(get_config))
            .route("/admin", web::get().to(check_admin))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
